const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
const token = auth.slice(7);
try {
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');
  if (!payload.tenant_id) throw new Error('No tenant_id');
  const body = $input.first().json.body || {};
  const projectId = (body.project_id || '').trim();
  if (!projectId) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'project_id requerido' } }];
  return [{ json: {
    user_id: payload.sub,
    tenant_id: payload.tenant_id,
    role: payload.role || 'architect',
    project_id: projectId,
    anio_construccion_override: body.anio_construccion ? parseInt(body.anio_construccion, 10) : null,
    numero_plantas_override: body.numero_plantas ? parseInt(body.numero_plantas, 10) : null,
    numero_viviendas_override: body.numero_viviendas ? parseInt(body.numero_viviendas, 10) : null,
    tipologia_override: body.tipologia_edificio || null,
    tiene_inspeccion: body.tiene_inspeccion === true || body.tiene_inspeccion === 'true',
    request_id: 'req_' + Math.random().toString(36).slice(2, 10)
  }}];
} catch (e) {
  return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message } }];
}

const row = $input.first()?.json;
const sess = $('Decode JWT + Body').first().json;
if (!row || !row.id) {
  return [{ json: { _error: 'PROJECT_NOT_FOUND', _status: 404, _details: 'project_id no existe o sin acceso por RLS' } }];
}
const anioConstruccion = sess.anio_construccion_override || row.edad_edificio_meta;
if (!anioConstruccion) {
  return [{ json: { _error: 'NO_ANIO_CONSTRUCCION', _status: 422, _details: 'anio_construccion requerido (en body o en projects.metadata.edad_edificio). El IEE necesita la edad del edificio para evaluar.' } }];
}
const hasNeighbors = !!(row.accesibilidad_output || row.energia_output);
const confidenceBase = hasNeighbors ? 0.85 : 0.7;

return [{ json: {
  ...sess,
  project: {
    id: row.id,
    name: row.name,
    project_type: row.project_type,
    location_address: row.location_address,
    location_city: row.location_city,
    location_province: row.location_province,
    property_type: row.property_type,
    property_area_m2: row.property_area_m2 ? parseFloat(row.property_area_m2) : null,
    notes: row.notes,
    anio_construccion: anioConstruccion,
    numero_plantas: sess.numero_plantas_override || row.numero_plantas_meta || 1,
    numero_viviendas: sess.numero_viviendas_override || row.numero_viviendas_meta || 1,
    tipologia_edificio: sess.tipologia_override || row.tipologia_meta || row.property_type || 'vivienda_unifamiliar'
  },
  agentes_vecinos: {
    accesibilidad: row.accesibilidad_output || null,
    energia: row.energia_output || null,
    has_neighbors: hasNeighbors
  },
  normativa_confidence_base: confidenceBase
}}];

const ctx = $input.first().json;
const project = ctx.project;
const v = ctx.agentes_vecinos;

const accesibilidadText = v.accesibilidad
  ? `Datos de agent_accessibility (commit previo):
${JSON.stringify(v.accesibilidad).slice(0, 800)}`
  : '(agent_accessibility no se ha ejecutado para este proyecto - inferir basicamente desde tipologia y antiguedad)';
const energiaText = v.energia
  ? `Datos de agent_energy_assessor (commit previo):
${JSON.stringify(v.energia).slice(0, 800)}`
  : '(agent_energy_assessor no se ha ejecutado - estimar letra E o F por defecto en edificios pre-CTE 2006)';

const antiguedad = new Date().getFullYear() - project.anio_construccion;

const systemPrompt = `Eres agent_iee, tecnico redactor de Informes de Evaluacion de Edificios (IEE) conforme a la normativa espanola: Ley 8/2013 de rehabilitacion regeneracion y renovacion urbanas, RD 233/2013 (modelo Anexo II), RD 7/2015 Texto Refundido Ley del Suelo y ordenanzas municipales aplicables.

REGLAS DE ORO:
- DEVUELVE SOLO JSON valido, sin texto fuera del JSON.
- Para cada bloque (estado, accesibilidad, energia) si no tienes datos suficientes, marca observaciones con "verificar in situ" en lugar de inventar.
- normativa_confidence_base ya viene calculado: ${ctx.normativa_confidence_base} (subelo a 0.9 si los datos vecinos son completos, bajalo a 0.5 si tuviste que inferir mucho).
- El arquitecto firma. Tu propones.`;

const userPrompt = `PROYECTO:
- Nombre: ${project.name}
- Direccion: ${project.location_address ?? '?'}, ${project.location_city ?? '?'}, ${project.location_province ?? '?'}
- Anio construccion: ${project.anio_construccion} (antiguedad: ${antiguedad} anos)
- Tipologia: ${project.tipologia_edificio}
- Plantas: ${project.numero_plantas}
- Viviendas: ${project.numero_viviendas}
- Superficie: ${project.property_area_m2 ?? '?'} m2
- Notas arquitecto: ${project.notes ? project.notes.slice(0, 300) : '(sin notas)'}

DATOS DE AGENTES VECINOS:
${accesibilidadText}

${energiaText}

NORMATIVA APLICABLE:
- Ley 8/2013 de rehabilitacion, regeneracion y renovacion urbanas
- RD 233/2013 Anexo II (modelo IEE)
- RD 7/2015 Texto refundido Ley del Suelo
- Ordenanzas municipales de ${project.location_city ?? 'el municipio correspondiente'}

TAREAS:
1. Evaluar ESTADO DE CONSERVACION: estructura, cubierta, fachadas, instalaciones. Calificacion: favorable / desfavorable.
2. Evaluar CONDICIONES BASICAS DE ACCESIBILIDAD: cumple / no cumple + ajustes razonables.
3. Evaluar CERTIFICACION ENERGETICA: importar de agent_energy_assessor si hay, o estimar letra A-G razonable.
4. Generar CALIFICACION GLOBAL (A-G) ponderada de los 3 bloques.
5. Listar RECOMENDACIONES priorizadas: actuaciones urgentes / convenientes con coste estimado.
6. Listar DOCUMENTOS A GENERAR (informe principal IEE + anexo fotografico).

OUTPUT (JSON estricto):
{
  "estado_conservacion": {
    "estructura": "favorable|desfavorable",
    "cubiertas": "favorable|desfavorable",
    "fachadas": "favorable|desfavorable",
    "instalaciones": "favorable|desfavorable",
    "calificacion": "favorable|desfavorable",
    "observaciones": "..."
  },
  "condiciones_accesibilidad": {
    "cumple": false,
    "ajustes_necesarios": ["..."],
    "ajustes_razonables": true,
    "observaciones": "..."
  },
  "eficiencia_energetica": {
    "letra": "E",
    "kgCO2_m2_anyo": 32.4,
    "kWh_m2_anyo": 156,
    "observaciones": "..."
  },
  "calificacion_global": "C",
  "recomendaciones": [
    { "prioridad": "urgente|conveniente", "actuacion": "...", "coste_estimado_eur": 8500, "justificacion": "..." }
  ],
  "documentos_a_generar": ["IEE_completo.pdf", "Anexo_fotografico.pdf"],
  "normativa_confidence": 0.85,
  "citation_source": "Ley 8/2013 art.4 + RD 233/2013 Anexo II + Ordenanza ${project.location_city ?? 'municipal'}"
}`;

return [{ json: {
  ...ctx,
  llm_payload: {
    model: 'gpt-4o-mini',
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userPrompt }
    ],
    temperature: 0.2,
    max_tokens: 1800,
    response_format: { type: 'json_object' }
  }
}}];

