const llm = $input.first()?.json;
const ctx = $('Build Context').first().json;
const project = ctx.project;
const raw = llm?.choices?.[0]?.message?.content || '{}';
let parsed;
try { parsed = JSON.parse(raw); } catch (e) {
  return [{ json: { _error: 'LLM_INVALID_JSON', _status: 502, _details: e.message } }];
}
const usage = llm?.usage || {};

const calificacionGlobal = ['A','B','C','D','E','F','G'].includes(parsed.calificacion_global) ? parsed.calificacion_global : null;

const draftContent = {
  estado_conservacion: parsed.estado_conservacion || {},
  condiciones_accesibilidad: parsed.condiciones_accesibilidad || {},
  eficiencia_energetica: parsed.eficiencia_energetica || {},
  calificacion_global: calificacionGlobal,
  recomendaciones: parsed.recomendaciones || [],
  documentos_a_generar: parsed.documentos_a_generar || ['IEE_completo.pdf'],
  normativa_confidence: parsed.normativa_confidence ?? ctx.normativa_confidence_base,
  citation_source: parsed.citation_source || 'Ley 8/2013 + RD 233/2013 Anexo II',
  agentes_vecinos_disponibles: ctx.agentes_vecinos.has_neighbors
};

return [{ json: {
  user_id: ctx.user_id,
  tenant_id: ctx.tenant_id,
  project_id: project.id,
  request_id: ctx.request_id,
  estado_conservacion_text: parsed.estado_conservacion?.calificacion || null,
  condiciones_accesibilidad_text: parsed.condiciones_accesibilidad?.cumple === true ? 'cumple' : 'no cumple',
  eficiencia_energetica_text: parsed.eficiencia_energetica?.letra || null,
  calificacion_global: calificacionGlobal,
  recomendaciones: parsed.recomendaciones || [],
  recomendaciones_count: (parsed.recomendaciones || []).length,
  draft_content: draftContent,
  model: llm?.model || 'gpt-4o-mini',
  tokens_in: usage.prompt_tokens || 0,
  tokens_out: usage.completion_tokens || 0
}}];

